#!/usr/bin/env python3
"""Prints the git filter-repo paths file for the `upstream` branch.

Selects EVerest's lib/everest/{cbv2g,iso15118,slac,util} and their older locations, follows every rename into them
back to its origin, and maps everything to the repo root. A path whose later history belongs to another file is
not followed, so no foreign history is pulled in.

usage: trace_paths.py <EVerest repo> [ref]
"""
import subprocess
import sys

PREFIXES = {
    'lib/everest/cbv2g/': 'cbv2g/',
    'lib/everest/iso15118/': 'iso15118/',
    'lib/everest/slac/': 'slac/',
    'lib/everest/util/': 'util/',
    'lib/staging/slac/': 'slac/',
    'lib/staging/util/': 'util/',
}


def main():
    repo = sys.argv[1]
    ref = sys.argv[2] if len(sys.argv) > 2 else 'main'
    log = subprocess.run(['git', '-C', repo, 'log', '--format=C %H', '--name-status', '-M', ref],
                         capture_output=True, text=True, check=True).stdout
    renames = []  # (commit, old path, new path), newest first
    commit = None
    for line in log.splitlines():
        if line.startswith('C '):
            commit = line[2:]
        elif line.startswith('R'):
            _, old, new = line.split('\t')
            renames.append((commit, old, new))

    files = {}

    def mapped(path):
        for prefix, target in PREFIXES.items():
            if path.startswith(prefix):
                return target + path[len(prefix):]
        return files.get(path)

    changed = True
    while changed:
        changed = False
        for commit, old, new in renames:
            target = mapped(new)
            if target and mapped(old) is None:
                # The old path must not carry other history after it moved here.
                later = subprocess.run(['git', '-C', repo, 'rev-list', '--count', f'{commit}..{ref}', '--', old],
                                       capture_output=True, text=True, check=True).stdout.strip()
                if later != '0':
                    print(f'warning: {old} has {later} commits after it moved, not followed', file=sys.stderr)
                    continue
                files[old] = target
                changed = True

    print('# Select (original paths), then rename to the repo root. Generated by trace_paths.py.')
    for prefix in PREFIXES:
        print(prefix)
    for old in sorted(files):
        print(f'literal:{old}')
    print('LICENSE')
    print()
    for prefix, target in PREFIXES.items():
        print(f'{prefix}==>{target}')
    for old in sorted(files):
        print(f'literal:{old}==>{files[old]}')


if __name__ == '__main__':
    main()
